import{_ as e}from"./chunks/03-http-shoulders.BvvQ0NqT.js";import{_ as o,o as d,c as a,a2 as r}from"./chunks/framework.BauHmMU1.js";const b=JSON.parse('{"title":"第三幕 · 站在 HTTP 的肩膀上","description":"","frontmatter":{},"headers":[],"relativePath":"comics/03-http-shoulders.md","filePath":"comics/03-http-shoulders.md","lastUpdated":1792595797000}'),s={name:"comics/03-http-shoulders.md"};function l(c,t,i,h,n,p){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="第三幕-·-站在-http-的肩膀上" tabindex="-1">第三幕 · 站在 HTTP 的肩膀上 <a class="header-anchor" href="#第三幕-·-站在-http-的肩膀上" aria-label="Permalink to &quot;第三幕 · 站在 HTTP 的肩膀上&quot;">​</a></h1><p><img src="'+e+'" alt="WebSocket 与 HTTP 的联系和区别"></p><blockquote><p>对应主线教程：<a href="./../03-http-vs-websocket">第 3 章 WebSocket 与 HTTP 的区别与联系</a></p></blockquote><h2 id="三种联系" tabindex="-1">三种联系 <a class="header-anchor" href="#三种联系" aria-label="Permalink to &quot;三种联系&quot;">​</a></h2><ol><li><strong>握手复用 HTTP</strong>：一个标准 HTTP GET + <code>Upgrade</code> 完成升级</li><li><strong>共用端口</strong>：<code>ws://</code> 走 80、<code>wss://</code> 走 443，与 HTTP/HTTPS 一致——能顺利穿过绝大多数防火墙和代理</li><li><strong>复用基础设施</strong>：Cookies、TLS 证书、Nginx 反向代理、负载均衡、网关鉴权原样可用</li></ol><h2 id="核心区别" tabindex="-1">核心区别 <a class="header-anchor" href="#核心区别" aria-label="Permalink to &quot;核心区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>HTTP</th><th>WebSocket</th></tr></thead><tbody><tr><td>通信模式</td><td>半双工，一问一答</td><td>全双工，随时互发</td></tr><tr><td>连接性质</td><td>短连接，逐请求</td><td>持久长连接</td></tr><tr><td>头部开销</td><td>每次几百字节</td><td>帧头最小 2 字节</td></tr><tr><td>服务端推送</td><td>不支持</td><td>原生支持</td></tr><tr><td>状态</td><td>无状态</td><td>连接本身即会话</td></tr><tr><td>URI</td><td><code>http://</code> / <code>https://</code></td><td><code>ws://</code> / <code>wss://</code></td></tr></tbody></table><h2 id="选型三岔口" tabindex="-1">选型三岔口 <a class="header-anchor" href="#选型三岔口" aria-label="Permalink to &quot;选型三岔口&quot;">​</a></h2><ul><li>偶尔获取、CRUD、可被 CDN 缓存 → <strong>HTTP</strong></li><li>服务端单向低频推送（通知、工单提醒）→ <strong>SSE</strong>，更简单且自带重连</li><li>双向高频、实时性要求高（聊天、协同、行情、游戏）→ <strong>WebSocket</strong></li></ul><p>真实项目中两者共存：HTTP API 负责登录与数据查询，WebSocket 负责实时推送。</p><hr><p>上一幕：<a href="./02-connection-life">第二幕</a> ｜ 下一幕：<a href="./04-node-lab">第四幕 · Node 实验室</a></p>',12)])])}const u=o(s,[["render",l]]);export{b as __pageData,u as default};
